 				return command
 			}
 		}
-		if searchVerifyGradleProjectBoundary(dir, evidence) {
-			return nil
+		if searchVerifyBlocksAncestorGradle(dir, evidence) {
+			gradleBlocked = true
 		}
 		if dir == "" {
 			break
